// Same workload as the PR's CountSetBits benchmark: random buffer, offset 0.
#include <chrono>
#include <cstdio>
#include <cstdint>
#include <memory>
#include <random>
#include <vector>
#include "arrow/util/bitmap_ops.h"

int main(int argc, char** argv) {
  const int64_t sizes[] = {1 << 4, 1 << 10, 1 << 17};
  const int64_t reps[] = {40000000, 4000000, 200000};
  std::mt19937_64 rng(42);
  double total = 0;
  int64_t sink = 0;
  for (int s = 0; s < 3; ++s) {
    std::vector<uint8_t> buf(sizes[s]);
    for (auto& b : buf) b = static_cast<uint8_t>(rng());
    auto t0 = std::chrono::steady_clock::now();
    for (int64_t i = 0; i < reps[s]; ++i) {
      int64_t c = arrow::internal::CountSetBits(buf.data(), 0, sizes[s] * 8);
      asm volatile("" : "+r"(c));
      sink += c;
    }
    auto t1 = std::chrono::steady_clock::now();
    total += std::chrono::duration<double>(t1 - t0).count();
  }
  FILE* f = fopen("countbits_out.txt", "w");
  fprintf(f, "%lld\n", (long long)sink);
  fclose(f);
  printf("PERFPROOF {\"value\": %.6f}\n", total);
  return 0;
}
EOF
